#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

banner "Jefi: Apple signing and notarization"

stage "Xcode command line tools: accept the licence"
say "notarytool refuses to run until the Xcode licence is accepted on this Mac."
say "This is the one step that needs your admin password."
note "Command: sudo xcodebuild -license accept"
if sudo xcodebuild -license accept 2>/dev/null; then
  printf '  %s✓%s licence accepted\n' "$GREEN" "$RESET"
else
  warn "couldn't accept it automatically. Run this yourself, then come back:"
  note "  sudo xcodebuild -license"
  pause "Press Enter once that's done."
fi

stage "Developer ID certificate"
say "Signing needs a 'Developer ID Application' certificate in your login keychain."
FOUND=$(security find-identity -v -p codesigning 2>/dev/null | grep "Developer ID Application" || true)
if [[ -n "$FOUND" ]]; then
  printf '  %s✓ found:%s\n' "$GREEN" "$RESET"
  printf '%s\n' "$FOUND" | sed 's/^/    /'
else
  warn "none installed."
  say "Create one, download it, and double-click the .cer to install:"
  open_url "https://developer.apple.com/account/resources/certificates/add"
  step "Choose 'Developer ID Application', follow the CSR steps, download, double-click."
  pause "Press Enter once it shows in Keychain Access."
fi
say "Copy the identity exactly as shown between the quotes above."
ask MACOS_SIGNING_IDENTITY "Signing identity:"
write_env MACOS_SIGNING_IDENTITY "$MACOS_SIGNING_IDENTITY"
# The Team ID is the code in brackets at the end of the identity.
APPLE_TEAM_ID=$(printf '%s' "$MACOS_SIGNING_IDENTITY" | sed -n 's/.*(\([A-Z0-9]*\))$/\1/p')
if [[ -n "$APPLE_TEAM_ID" ]]; then
  printf '  %s✓%s Team ID read from the identity: %s\n' "$GREEN" "$RESET" "$APPLE_TEAM_ID"
else
  ask APPLE_TEAM_ID "Team ID (10 characters):"
fi
write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"

stage "Apple ID and an app-specific password"
say "Notarization signs in as you, with a password made just for this."
say "Your normal Apple ID password will NOT work."
ask APPLE_ID "Apple ID email:"
write_env APPLE_ID "$APPLE_ID"
open_url "https://appleid.apple.com/account/manage"
step "Sign in, then: Sign-In and Security → App-Specific Passwords → +"
step "Name it 'Jefi notarization' and copy the password (xxxx-xxxx-xxxx-xxxx)."
warn "Apple shows it once. Copy it before closing the dialog."
ask_secret APPLE_APP_SPECIFIC_PASSWORD "Paste the app-specific password:"
# Deliberately not written to .env: it lives in the keychain (next stage) and in GitHub.

stage "Save the credentials for notarytool"
say "Storing them once means releases don't need the password on the command line."
if xcrun notarytool store-credentials jefi \
     --apple-id "$APPLE_ID" --team-id "$APPLE_TEAM_ID" --password "$APPLE_APP_SPECIFIC_PASSWORD"; then
  write_env JEFI_NOTARY_PROFILE "jefi"
  printf '  %s✓%s saved as the "jefi" profile\n' "$GREEN" "$RESET"
else
  warn "notarytool wouldn't take them. The usual cause is a mistyped password."
  SKIPPED+=("xcrun notarytool store-credentials jefi (re-run this wizard)")
fi

stage "Export the certificate for CI"
say "GitHub needs the certificate itself, as a password-protected .p12 file."
say "Only Keychain Access can export it, so this part is by hand."
open -a "Keychain Access" 2>/dev/null || warn "open Keychain Access yourself (Applications → Utilities)."
step "In Keychain Access: login → My Certificates → find your Developer ID Application."
step "Right-click it → Export… → format 'Personal Information Exchange (.p12)'."
step "Save it to your Desktop as jefi-signing.p12."
step "It asks for a password to protect the file: make one up and keep it."
pause "Press Enter once the .p12 is saved."
ask P12_PATH "Path to the .p12 [~/Desktop/jefi-signing.p12]:"
[[ -z "$P12_PATH" ]] && P12_PATH="$HOME/Desktop/jefi-signing.p12"
P12_PATH="${P12_PATH/#\~/$HOME}"
if [[ -f "$P12_PATH" ]]; then
  MACOS_CERT_P12_BASE64=$(base64 -i "$P12_PATH" | tr -d '\n')
  printf '  %s✓%s read %s\n' "$GREEN" "$RESET" "$P12_PATH"
else
  warn "no file at $P12_PATH"
  MACOS_CERT_P12_BASE64=""
  SKIPPED+=("MACOS_CERT_P12_BASE64 (export the .p12 and re-run)")
fi
ask_secret MACOS_CERT_PASSWORD "The password you just gave the .p12:"

stage "GitHub secrets for the release workflow"
say "These let a tagged release build, sign and notarize without you."
if [[ -n "$MACOS_CERT_P12_BASE64" ]]; then set_secret MACOS_CERT_P12_BASE64 "$MACOS_CERT_P12_BASE64"; fi
set_secret MACOS_CERT_PASSWORD "$MACOS_CERT_PASSWORD"
set_secret MACOS_SIGNING_IDENTITY "$MACOS_SIGNING_IDENTITY"
set_secret APPLE_ID "$APPLE_ID"
set_secret APPLE_TEAM_ID "$APPLE_TEAM_ID"
set_secret APPLE_APP_SPECIFIC_PASSWORD "$APPLE_APP_SPECIFIC_PASSWORD"
note "The release job runs in the 'release' environment; repo secrets reach it."
note "To keep them environment-only instead: Settings → Environments → release."
if [[ -f "$P12_PATH" ]] && confirm "Delete $P12_PATH now that it's in GitHub?"; then
  rm -f "$P12_PATH" && printf '  %s✓%s deleted\n' "$GREEN" "$RESET"
fi

stage "Sign and notarize, for real"
say "This builds the app, signs it, and sends the DMG to Apple."
say "Apple usually answers in a few minutes; it can take longer."
if confirm "Run it now?"; then
  if JEFI_NOTARY_PROFILE=jefi bun scripts/release/sign.ts --notarize; then
    printf '\n  %s✓ Jefi is signed and notarized.%s It opens on any Mac with no warning.\n' "$GREEN" "$RESET"
  else
    warn "that didn't finish. The output above says why; re-run with:"
    note "  JEFI_NOTARY_PROFILE=jefi bun scripts/release/sign.ts --notarize"
  fi
else
  SKIPPED+=("JEFI_NOTARY_PROFILE=jefi bun scripts/release/sign.ts --notarize")
fi
finish
